function compressCssSelector(selector: string) {
  return selector
    .replace(/\.(?=\s|$)/g, '')
    .replace(/\.ub-[^. [:]+/g, '')
    .replace(/^(\w+ > )+/, '')
    .replace(/(^| )\w+?(?=\.)/g, '$1')
    .replace(/ > /g, ' >');
}

mustGetNode(id: NodeID) {
