function buildSubtree(span: IOtelSpan): IFlameNode {
  const children: IFlameNode[] = [];
  for (const child of span.childSpans) {
    children.push(buildSubtree(child));
  }

  const grouped = groupChildrenByName(children);

  return {
    name: `${span.resource.serviceName}: ${span.name}`,
    serviceName: span.resource.serviceName,
    value: span.duration,
    duration: span.duration,
    count: 1,
    children: grouped,
  };
}

get focalPath(): PathElem[] {
  const result: PathElem[] = [];
  let current: PathElem | null = this;
  while (current) {
    result.push(current);
    current = current.focalSideNeighbor;
  }
  if (this.distance > 0) result.reverse();
  return result;
}

