function formatErrorForGA(
  error: IErrorData,
  context: IErrorContext
): {
  message: string;
  category: string;
  action: string;
  label: string;
  value: number;
} {
  const errorType = error.name || 'Error';
  const errorValue = error.message || 'Unknown error';

  // Format message
  const message = truncate(formatErrorMessage(`${errorType}: ${errorValue}`), 149);

  // Format stack trace
  const stack = formatStackForGA(error.stack);

  // Get page info
  const url = truncate(context.url.replace(getOrigin(), ''), 50);
  const { word: page } = getSym(NAV_SYMBOLS, url);

  // Calculate duration
  const value = Math.round(context.sessionDuration / 1000);

  // Build category
  const category = `jaeger/${page}/error`;

  // Build action (message + tags + url + stack)
  let action = [message, context.tags.git, url, '', stack].filter(v => v != null).join('\n');
  action = truncate(action, 499);

  // Build label (message + page + duration + git + breadcrumbs)
  const header = [message, page, value, context.tags.git, ''].filter(v => v != null).join('\n');
  const crumbs = formatBreadcrumbs(context.breadcrumbs);
  const label = `${header}\n${truncate(crumbs, 498 - header.length, true)}`;

  return {
    message,
    category,
    action,
    label,
    value,
  };
}

public getVisWithUpdatedGeneration(
  vertexKey: string,
  direction: EDirection,
  visEncoding?: string
): { visEncoding: string; update: ECheckedStatus } | null {
  const generationElems = this.getGeneration(vertexKey, direction, visEncoding);
  const currCheckedStatus = this.getGenerationVisibility(vertexKey, direction, visEncoding);
  if (!generationElems.length || !currCheckedStatus) return null;

  if (currCheckedStatus === ECheckedStatus.Full) {
    return {
      visEncoding: this.getVisWithoutElems(generationElems, visEncoding),
      update: ECheckedStatus.Empty,
    };
  }

  return {
    visEncoding: this.getVisWithElems(generationElems, visEncoding),
    update: ECheckedStatus.Full,
  };
}

