import ease from 'tween-functions';

import { TNil } from '../../types';

interface ITweenState {
  done: boolean;
  value: number;
}

type TTweenCallback = (state: ITweenState) => void;

type TTweenOptions = {
  delay?: number;
  duration: number;
  from: number;
  onComplete?: TTweenCallback;
  onUpdate?: TTweenCallback;
  to: number;
};

export default class Tween {
  callbackComplete: TTweenCallback | TNil;
  callbackUpdate: TTweenCallback | TNil;
  delay: number | TNil;
  duration: number;
  from: number;
  requestID: number | TNil;
  startTime: number;
  timeoutID: number | TNil;
  to: number;

  constructor({ duration, from, to, delay, onUpdate, onComplete }: TTweenOptions) {
    this.startTime = Date.now() + (delay || 0);
    this.duration = duration;
    this.from = from;
    this.to = to;
    if (!onUpdate && !onComplete) {
      this.callbackComplete = undefined;
      this.callbackUpdate = undefined;
      this.timeoutID = undefined;
      this.requestID = undefined;
    } else {
      this.callbackComplete = onComplete;
      this.callbackUpdate = onUpdate;
      if (delay) {
        // setTimeout from @types/node returns NodeJS.Timeout, so prefix with `window.`
        this.timeoutID = window.setTimeout(this._frameCallback, delay);
        this.requestID = undefined;
      } else {
        this.requestID = window.requestAnimationFrame(this._frameCallback);
        this.timeoutID = undefined;
      }
    }
  }

  _frameCallback = () => {
    this.timeoutID = undefined;
    this.requestID = undefined;
    const current = Object.freeze(this.getCurrent());
    if (this.callbackUpdate) {
      this.callbackUpdate(current);
    }
    if (this.callbackComplete && current.done) {
      this.callbackComplete(current);
    }
    if (current.done) {
      this.callbackComplete = undefined;
      this.callbackUpdate = undefined;
    } else {
      this.requestID = window.requestAnimationFrame(this._frameCallback);
    }
  };

  cancel() {
    if (this.timeoutID != null) {
      clearTimeout(this.timeoutID);
      this.timeoutID = undefined;
    }
    if (this.requestID != null) {
      window.cancelAnimationFrame(this.requestID);
      this.requestID = undefined;
    }
    this.callbackComplete = undefined;
    this.callbackUpdate = undefined;
  }

  getCurrent(): ITweenState {
    const t = Date.now() - this.startTime;
    if (t <= 0) {
      // still in the delay period
      return { done: false, value: this.from };
    }
    if (t >= this.duration) {
      // after the expiration
      return { done: true, value: this.to };
    }
    // mid-tween
    return { done: false, value: ease.easeOutQuint(t, this.from, this.to, this.duration) };
  }
}

export function decodeSvcFilter(
  sortedServiceNames: ReadonlyArray<string>,
  encoded: string
): { visibleServices: Set<string>; stale: boolean } | null {
  if (!encoded || sortedServiceNames.length === 0) return null;

  const dotIndex = encoded.indexOf('.');
  if (dotIndex < 1) return null;

  const checksumHex = encoded.slice(0, dotIndex);
  const bitmaskHex = encoded.slice(dotIndex + 1);
  if (!bitmaskHex) return null;

  // svcChecksum() always produces exactly 4 hex chars.
  // Reject malformed checksum segments as invalid rather than stale.
  if (checksumHex.length !== 4 || !/^[\da-f]{4}$/i.test(checksumHex)) return null;

  const currentChecksum = svcChecksum(sortedServiceNames);
  if (checksumHex.toLowerCase() !== currentChecksum.toLowerCase()) {
    return { visibleServices: new Set(sortedServiceNames), stale: true };
  }

  // Reject overly long bitmasks to avoid expensive BigInt parsing from crafted URLs.
  const maxHexLen = Math.ceil(sortedServiceNames.length / 4) + 1;
  if (bitmaskHex.length > maxHexLen || !/^[\da-f]+$/i.test(bitmaskHex)) return null;

  let mask: bigint;
  try {
    mask = BigInt(`0x${bitmaskHex}`);
  } catch {
    return null;
  }

  if (mask === BigInt(0)) return null;

  const visibleServices = new Set<string>();
  for (let i = 0; i < sortedServiceNames.length; i++) {
    if (mask & (BigInt(1) << BigInt(i))) {
      visibleServices.add(sortedServiceNames[i]);
    }
  }

  // No in-range bits set → invalid filter (would prune everything)
  if (visibleServices.size === 0) return null;

  // All visible → no filter
  if (visibleServices.size === sortedServiceNames.length) return null;

  return { visibleServices, stale: false };
}

getRgbColorByKey(key: string): [number, number, number] {
  const color = this.colors[this._getColorIndex(key)];
  // Read the property name off `this.colors` rather than the module-level list,
  // so a generator built with a custom palette resolves its own colors.
  const varName = CSS_VAR_REFERENCE.exec(color)?.[1];
  if (!varName) {
    // A literal color needs no lookup.
    return strToRgb(color);
  }
  if (typeof window !== 'undefined' && typeof window.getComputedStyle === 'function') {
    const hex = window.getComputedStyle(getThemedElement()).getPropertyValue(varName);
    if (hex) {
      return strToRgb(hex);
    }
  }
  // Fallback or default if window is not available (e.g. tests or server-side)
  return [0, 0, 0];
}

