  onClick?: () => void;
};

export default function ReferenceLink(props: ReferenceLinkProps) {
  const { link, children, className, focusSpan, ...otherProps } = props;
  delete otherProps.onClick;

  // link within the trace should have link.span defined
  const isSameTrace = link.span !== undefined;

  if (isSameTrace) {
    return (
      <a role="button" onClick={() => focusSpan(link.spanID)} className={className} {...otherProps}>
        {children}
      </a>
    );
  }

  return (
    <a
      href={getUrl(link.traceID, link.spanID)}
      target="_blank"
      rel="noopener noreferrer"
      className={className}
      {...otherProps}
    >
      {children}
    </a>
  );
}

addNode(id: NodeID, parentID: NodeID | null, data: TData) {
  if (this.hasNode(id)) {
    throw new Error(`Node already added: ${JSON.stringify(id)}`);
  }
  const node: TDagNode<TData> = {
    ...data,
    id,
    parentID,
    children: new Set(),
  };
  this.nodesMap.set(id, node);
  if (!parentID) {
    this.rootIDs.add(id);
  } else {
    const parentNode = this.nodesMap.get(parentID);
    if (parentNode) {
      parentNode.children.add(id);
    }
  }
  return node;
}

