type Props = {
  x: number;
  y: number;
  onReset: () => void;
  onCollapseAbove: () => void;
  onCopyName: () => void;
  onHighlightSimilar: () => void;
  onClose: () => void;
  isDirty: boolean;
  chartZoomed: boolean;
};

const FlamegraphContextMenu = ({
  x,
  y,
  onReset,
  onCollapseAbove,
  onCopyName,
  onHighlightSimilar,
  onClose,
  isDirty,
  chartZoomed,
}: Props) => {
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        onClose();
      }
    };
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('mousedown', handleClick);
    document.addEventListener('keydown', handleEsc);
    return () => {
      document.removeEventListener('mousedown', handleClick);
      document.removeEventListener('keydown', handleEsc);
    };
  }, [onClose]);

  return (
    <div ref={menuRef} className="Flamegraph-context-menu" style={{ left: x, top: y }}>
      <button className="Flamegraph-context-menu--item" disabled={!isDirty} onClick={onReset} type="button">
        <IoRefreshOutline />
        Reset View
      </button>
      <button
        className="Flamegraph-context-menu--item"
        disabled={!chartZoomed}
        onClick={onCollapseAbove}
        type="button"
      >
        <TbArrowMerge />
        Collapse nodes above
      </button>
      <button className="Flamegraph-context-menu--item" onClick={onCopyName} type="button">
        <IoCopyOutline />
        Copy function name
      </button>
      <button className="Flamegraph-context-menu--item" onClick={onHighlightSimilar} type="button">
        <MdHighlight />
        Highlight similar nodes
      </button>
    </div>
  );
};

export default FlamegraphContextMenu;

export default function BreakableText({ className = 'BreakableText', text, wordRegexp = WORD_RX }: Props) {
  if (!text) {
    return typeof text === 'string' ? text : null;
  }
  const spans = [];
  wordRegexp.exec('');
  // if the given text has no words, set the first match to the entire text
  let match: RegExpExecArray | string[] | null = wordRegexp.exec(text) || [text];
  while (match) {
    spans.push(
      <span key={`${text}-${spans.length}`} className={className}>
        {match[0]}
      </span>
    );
    match = wordRegexp.exec(text);
  }
  return spans;
}

